<script setup lang="ts">
import {ref} from 'vue'
import {NButton,NInput,NModal,NSelect,NCheckbox} from 'naive-ui'
import {request} from '../api/client'
import {money,kinds,type Account,type Location} from '../api/funds'
const props=defineProps<{mode:'accounts'|'locations';accounts:Account[];locations:Location[];editable:boolean}>()
const emit=defineEmits<{changed:[]}>()
const show=ref(false),id=ref(''),error=ref(''),busy=ref(false)
const name=ref(''),tags=ref(''),kind=ref('asset'),isFund=ref(false),custodian=ref('')
function edit(item?:Account|Location){id.value=item?.id||'';name.value=item?.name||'';tags.value=item?.tags.join(', ')||'';kind.value=(item as Account)?.kind||'asset';isFund.value=(item as Account)?.is_fund||false;custodian.value=(item as Location)?.custodian_label||'';error.value='';show.value=true}
async function save(){busy.value=true;error.value='';try{const body:Record<string,unknown>={name:name.value,tags:[...new Set(tags.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean))]};if(props.mode==='locations')body.custodian_label=custodian.value;else if(!id.value){body.kind=kind.value;body.is_fund=kind.value==='asset'&&isFund.value}await request(`/${props.mode}${id.value?'/'+id.value:''}`,id.value?'PATCH':'POST',body);show.value=false;emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="toolbar"><h2>{{mode==='accounts'?'记账对象':'存货地点目录'}}</h2><NButton v-if="editable" @click="edit()">新建</NButton></div><p v-if="mode==='locations'" class="muted">维护地点和保管人资料；本阶段尚无库存数量或存货账。</p><div class="table-wrap"><table><thead><tr><th>名称</th><th>{{mode==='accounts'?'类别':'保管人'}}</th><th v-if="mode==='accounts'">资金对象</th><th>标签</th><th v-if="mode==='accounts'">账面余额（元）</th><th v-if="editable">操作</th></tr></thead><tbody><template v-if="mode==='accounts'"><tr v-for="a in accounts" :key="a.id"><td>{{a.name}}<small>{{a.id}}</small></td><td>{{kinds[a.kind]}}</td><td>{{a.is_fund?'是':'否'}}</td><td><span v-for="tag in a.tags" :key="tag" class="tag">{{tag}}</span></td><td>{{money(a.balance_minor)}}</td><td v-if="editable"><NButton size="small" @click="edit(a)">编辑</NButton></td></tr></template><template v-else><tr v-for="a in locations" :key="a.id"><td>{{a.name}}<small>{{a.id}}</small></td><td>{{a.custodian_label||'—'}}</td><td><span v-for="tag in a.tags" :key="tag" class="tag">{{tag}}</span></td><td v-if="editable"><NButton size="small" @click="edit(a)">编辑</NButton></td></tr></template></tbody></table></div><NModal v-model:show="show" preset="card" :title="id?'编辑资料':'新建资料'" class="dialog"><label>名称<NInput v-model:value="name"/></label><label>标签（逗号分隔）<NInput v-model:value="tags"/></label><template v-if="mode==='accounts'&&!id"><label>类别<NSelect v-model:value="kind" :options="Object.entries(kinds).map(([value,label])=>({value,label}))"/></label><NCheckbox :checked="isFund" :disabled="kind!=='asset'" @update:checked="isFund=$event">资金对象（仅资产类别）</NCheckbox></template><label v-if="mode==='locations'">保管人<NInput v-model:value="custodian"/></label><p v-if="error" class="error">{{error}}</p><div class="actions"><NButton type="primary" :loading="busy" @click="save">保存</NButton></div></NModal></template>
